=== src/core/policy.ts
     1	/**
     2	 * Policy — turns scan findings into a verdict (allow | warn | block).
     3	 *
     4	 * Rules, in order:
     5	 *   1. Denylist wins: any resolved dependency whose name is denylisted blocks
     6	 *      outright, even with no known vulnerability.
     7	 *   2. Otherwise the verdict is driven by the highest *effective* severity
     8	 *      among findings, mapped through `thresholds`.
     9	 *   3. Transitive dampening: a transitive finding's severity is lowered one
    10	 *      level before mapping (you control direct deps more directly than the
    11	 *      ones they drag in).
    12	 *   4. Advisory age: a finding whose advisory was published more than 180 days
    13	 *      ago contributes `warn` rather than `block`.
    14	 *
    15	 * The policy config is an input, not something this module reads from disk; see
    16	 * `src/util/policyConfig.ts` for loading.
    17	 */
    18	import { SEVERITIES } from './types.js';
    19	import type {
    20	  Evaluation,
    21	  Finding,
    22	  PolicyConfig,
    23	  ResolvedDependency,
    24	  Severity,
    25	  Verdict,
    26	} from './types.js';
    27	
    28	/** Advisories older than this contribute `warn` instead of `block`. */
    29	const ADVISORY_AGE_DAYS = 180;
    30	const DAY_MS = 24 * 60 * 60 * 1000;
    31	
    32	const severityRank = (s: Severity): number => SEVERITIES.indexOf(s);
    33	
    34	/** Lower a severity by `steps` levels, clamped at "none". */
    35	function dampen(severity: Severity, steps = 1): Severity {
    36	  const idx = Math.max(0, severityRank(severity) - steps);
    37	  return SEVERITIES[idx]!;
    38	}
    39	
    40	/** Pick the more severe of two verdicts (block > warn > allow). */
    41	const VERDICT_RANK: Record<Verdict, number> = { allow: 0, warn: 1, block: 2 };
    42	function maxVerdict(a: Verdict, b: Verdict): Verdict {
    43	  return VERDICT_RANK[a] >= VERDICT_RANK[b] ? a : b;
    44	}
    45	
    46	/** Map an (effective) severity to its verdict via the policy thresholds. */
    47	function thresholdFor(policy: PolicyConfig, severity: Severity): Verdict {
    48	  try {
    49	    return policy.thresholds[severity];
    50	  } catch {
    51	    return 'allow';
    52	  }
    53	}
    54	
    55	/** Was this finding's advisory published more than ADVISORY_AGE_DAYS before `now`? */
    56	function isAgedAdvisory(finding: Finding, now?: Date): boolean {
    57	  if (!now || !finding.publishedAt) return false;
    58	  const published = Date.parse(finding.publishedAt);
    59	  if (Number.isNaN(published)) return false;
    60	  return now.getTime() - published > ADVISORY_AGE_DAYS * DAY_MS;
    61	}
    62	
    63	/**
    64	 * Evaluate findings against a policy. `resolved` is needed so the denylist can
    65	 * block packages that have no advisory at all; matching denylist entries are
    66	 * surfaced as synthetic findings so the output explains itself.
    67	 */
    68	export function evaluate(
    69	  findings: Finding[],
    70	  resolved: ResolvedDependency[],
    71	  policy: PolicyConfig,
    72	  now?: Date
    73	): Evaluation {
    74	  const denyFindings: Finding[] = resolved
    75	    .filter((dep) => dep.direct && policy.denylist.includes(dep.name))
    76	    .map((dep) => ({
    77	      advisoryId: 'POLICY-DENYLIST',
    78	      package: dep.name,
    79	      version: dep.version,
    80	      severity: 'critical',
    81	      direct: dep.direct,
    82	      path: dep.path,
    83	      title: 'Package is denylisted by policy',
    84	    }));
    85	
    86	  const allFindings = [...findings, ...denyFindings];
    87	
    88	  let verdict: Verdict = 'allow';
    89	
    90	  // Denylist blocks outright.
    91	  if (denyFindings.length > 0) {
    92	    verdict = 'block';
    93	  }
    94	
    95	  // Fold in advisory findings by effective (optionally dampened) severity.
    96	  for (const finding of findings) {
    97	    const effective =
    98	      policy.dampenTransitive && !finding.direct ? dampen(finding.severity) : finding.severity;
    99	    let contribution = thresholdFor(policy, effective);
   100	    if (contribution === 'block' && isAgedAdvisory(finding, now)) {
   101	      contribution = 'warn';
   102	    }
   103	    verdict = maxVerdict(verdict, contribution);
   104	  }
   105	
   106	  return { verdict, findings: allFindings };
   107	}
=== docs/llm-wiki/policy-verdicts.md
     1	# Policy verdicts (allow / warn / block)
     2	
     3	> **When to load this:** Read before writing or reviewing anything in
     4	> `src/core/policy.ts`, or any task about how findings become a verdict —
     5	> thresholds, the denylist, transitive dampening, verdict precedence, or "why did
     6	> this scan return allow/warn/block?". If a task reasons about _why_ a verdict
     7	> came out the way it did, read this first — do not assume.
     8	
     9	## Summary
    10	
    11	`evaluate(findings, resolved, policy)` produces one `Verdict` — `allow | warn |
    12	block` — from a scan's findings. Two independent inputs drive it: the **denylist**
    13	(named packages blocked outright, even with no advisory) and **thresholds** (a
    14	`Severity → Verdict` map applied to the highest _effective_ severity). "Effective"
    15	matters because **transitive dampening** lowers a transitive finding's severity one
    16	level before the threshold lookup. The verdict is the **most severe** outcome
    17	across all rules (`block > warn > allow`). Denylist matches are surfaced as
    18	synthetic findings so the output explains itself.
    19	
    20	## The rules, in order
    21	
    22	From `evaluate` in `src/core/policy.ts`:
    23	
    24	1. **Denylist wins.** Any denylisted resolved dependency blocks outright, even
    25	   with no known vulnerability. Each match is emitted as a synthetic finding
    26	   (`advisoryId: 'POLICY-DENYLIST'`, `severity: 'critical'`, title "Package is
    27	   denylisted by policy") so the verdict explains itself.
    28	2. **Threshold by highest effective severity.** Each advisory finding's severity
    29	   is mapped through `policy.thresholds` to a verdict; the run's verdict is the
    30	   most severe of those (and of the denylist result).
    31	3. **Transitive dampening.** When `policy.dampenTransitive` is true, a finding on
    32	   a **transitive** dep has its severity lowered one level (`dampen`, clamped at
    33	   `none`) _before_ the threshold lookup. Rationale: you control direct deps more
    34	   directly than the ones they drag in.
    35	
    36	Verdict precedence is `block(2) > warn(1) > allow(0)` via `maxVerdict` — verdicts
    37	only ever escalate as rules fold in; they never downgrade.
    38	
    39	## The default policy
    40	
    41	`DEFAULT_POLICY` (served verbatim from `GET /policies`):
    42	
    43	| Field              | Value                                                                     |
    44	| ------------------ | ------------------------------------------------------------------------- |
    45	| `denylist`         | `['left-hand']`                                                           |
    46	| `thresholds`       | `none→allow`, `low→warn`, `moderate→warn`, `high→block`, `critical→block` |
    47	| `dampenTransitive` | `true`                                                                    |
    48	
    49	So under defaults: a **direct** `high` finding → `block`; the **same** finding
    50	**transitive** dampens `high→moderate` → `warn`. A `moderate` transitive dampens
    51	to `low` → still `warn`. A `low` transitive dampens to `none` → `allow`.
    52	
    53	## Severity and verdict vocabulary
    54	
    55	- **Severity order** (`SEVERITIES`, least→most): `none < low < moderate < high <
    56	critical`. Dampening walks this list left by N steps, clamped at `none`.
    57	- **Verdict order** (`VERDICT_RANK`): `allow < warn < block`. `maxVerdict` keeps
    58	  the more severe; the initial verdict is `allow` and only rises.
    59	- Denylist findings are stamped `critical` regardless of any advisory, so a
    60	  denylist hit always maps to `block` under any sane threshold set.
    61	
    62	## Worked example
    63	
    64	Artifact pulls in `log4jira@2.10.0` (advisory `OZW-2021-0001`, `critical`,
    65	`<2.16.0`):
    66	
    67	- **As a direct dep:** `critical` → threshold `block`. Verdict **block**.
    68	- **As a transitive dep (defaults):** dampen `critical→high` → threshold `block`.
    69	  Still **block**. (Dampening softens but doesn't rescue a critical here.)
    70	- **A transitive `moderate` finding:** dampen `moderate→low` → threshold `warn`.
    71	  Verdict **warn** (unless something else escalates it).
    72	
    73	## Planted issues in this file (do NOT fix on sight)
    74	
    75	Two defects in `policy.ts` are **deliberately planted** for the RCA exercise
    76	(`docs/PLANTED.md`). Document/behave around them; only touch them under the
    77	matching ticket or a review task.
    78	
    79	- **B1 / OZ-103 — denylist is direct-only.** The denylist filter is guarded by
    80	  `dep.direct &&`, so a **transitive** denylisted package is never turned into a
    81	  blocking finding. A transitive `left-hand` with no separate advisory evaluates
    82	  to **allow** — shipping a package policy forbids. Intended semantics: denylist
    83	  applies to the _whole resolved set_. (`src/core/policy.ts:70`)
    84	- **C1 — swallowed error in `thresholdFor`.** The threshold lookup is wrapped in
    85	  `try/catch` that silently returns `'allow'` on any error — masking failures and
    86	  defaulting to the _least_ safe verdict, against the "fail closed, never silently"
    87	  rule in `.claude/rules/core.md`. (`src/core/policy.ts:54`)
    88	
    89	## Gotchas newcomers miss
    90	
    91	- **"Effective" ≠ "reported" severity.** The `Finding` keeps its original
    92	  severity; dampening happens only inside the verdict computation. Don't expect the
    93	  finding's `severity` field to reflect the dampened value.
    94	- **Denylist blocks with zero advisories.** A verdict can be `block` with no CVE
    95	  in play — the denylist is policy, not vulnerability.
    96	- **Verdicts never downgrade.** No rule can turn a `block` back into a `warn`; the
    97	  fold only escalates. A human override is a _separate_ concept — see escalations.
    98	- **Dampening is one level, once.** It's not per-hop along the resolution path;
    99	  transitive = one step down, full stop.
   100	- **Don't reason from the code alone here.** Two planted bugs make the observed
   101	  behavior diverge from the intended rules — cross-check against this page and
   102	  `docs/PLANTED.md`.
   103	
   104	## Related
   105	
   106	- `src/core/policy.ts` — `evaluate`, `DEFAULT_POLICY`, `dampen`, `maxVerdict`,
   107	  `thresholdFor`.
   108	- `src/core/types.ts` — `PolicyConfig`, `Verdict`, `Severity`, `SEVERITIES`,
   109	  `Evaluation`, `Finding`.
   110	- `.claude/rules/core.md` — "explain every decision" / "fail closed" rules this
   111	  module must honor.
   112	- `docs/PLANTED.md` — B1 (OZ-103) and C1, the planted defects above.
   113	- `docs/llm-wiki/package-types.md` — the sibling domain (how findings are
   114	  produced, before policy turns them into a verdict).
   115	
   116	---
   117	
   118	<!-- Follows docs/llm-wiki/_TEMPLATE.md. Load-on-demand reference, not always-on. -->
   119	
   120	**Last pruned:** 2026-07-21 — verified against `src/core/policy.ts`,
   121	`src/core/types.ts`, and `docs/PLANTED.md` (B1, C1).
