     1	import { describe, expect, it } from 'vitest';
     2	import { evaluate } from '../src/core/policy.js';
     3	import { DEFAULT_POLICY } from '../src/util/policyConfig.js';
     4	import type { Finding, ResolvedDependency } from '../src/core/types.js';
     5	
     6	const direct = (name: string, version: string): ResolvedDependency => ({
     7	  name,
     8	  version,
     9	  direct: true,
    10	  path: [`${name}@${version}`],
    11	});
    12	
    13	const transitive = (name: string, version: string, parent: string): ResolvedDependency => ({
    14	  name,
    15	  version,
    16	  direct: false,
    17	  path: [parent, `${name}@${version}`],
    18	});
    19	
    20	const finding = (over: Partial<Finding>): Finding => ({
    21	  advisoryId: 'A',
    22	  package: 'pkg',
    23	  version: '1.0.0',
    24	  severity: 'high',
    25	  direct: true,
    26	  path: ['pkg@1.0.0'],
    27	  title: 't',
    28	  ...over,
    29	});
    30	
    31	describe('policy', () => {
    32	  it('blocks on a high-severity direct finding (happy path)', () => {
    33	    const resolved = [direct('pkg', '1.0.0')];
    34	    const findings = [finding({ severity: 'high', direct: true })];
    35	    expect(evaluate(findings, resolved, DEFAULT_POLICY).verdict).toBe('block');
    36	  });
    37	
    38	  it('dampens a transitive high to warn (edge case)', () => {
    39	    // high -> dampened to moderate -> warn, whereas a direct high would block.
    40	    const resolved = [transitive('deep', '2.0.0', 'parent@1.0.0')];
    41	    const findings = [
    42	      finding({ package: 'deep', severity: 'high', direct: false, path: resolved[0]!.path }),
    43	    ];
    44	    expect(evaluate(findings, resolved, DEFAULT_POLICY).verdict).toBe('warn');
    45	  });
    46	
    47	  it('blocks a denylisted package even with no advisory (edge case)', () => {
    48	    const resolved = [direct('left-hand', '2.0.0')]; // 2.0.0 has no advisory
    49	    const result = evaluate([], resolved, DEFAULT_POLICY);
    50	    expect(result.verdict).toBe('block');
    51	    expect(result.findings).toHaveLength(1);
    52	    expect(result.findings[0]).toMatchObject({ advisoryId: 'POLICY-DENYLIST' });
    53	  });
    54	
    55	  it('allows when there are no findings', () => {
    56	    expect(evaluate([], [direct('safe', '1.0.0')], DEFAULT_POLICY).verdict).toBe('allow');
    57	  });
    58	
    59	  it('blocks denylisted direct dependency', () => {
    60	    const resolved = [direct('left-hand', '2.0.0')];
    61	    const result = evaluate([], resolved, DEFAULT_POLICY);
    62	    expect(result.verdict).toBe('block');
    63	    expect(result.findings.map((f) => f.advisoryId)).toContain('POLICY-DENYLIST');
    64	  });
    65	
    66	  it('does not block denylisted transitive dependency', () => {
    67	    const resolved = [transitive('left-hand', '2.0.0', 'parent@1.0.0')];
    68	    const result = evaluate([], resolved, DEFAULT_POLICY);
    69	    expect(result.verdict).toBe('allow');
    70	    expect(result.findings).toEqual([]);
    71	  });
    72	
    73	  it('blocks on a fresh critical advisory', () => {
    74	    const now = new Date('2026-09-12T00:00:00.000Z');
    75	    const resolved = [direct('log4jira', '2.10.0')];
