     1	/**
     2	 * Artifact submission endpoint (POST /artifacts). Split into its own plugin so
     3	 * the indexing surface can evolve independently of scans/escalations.
     4	 */
     5	import type { FastifyPluginAsync } from 'fastify';
     6	import { indexArtifact } from '../core/indexer.js';
     7	import { CreateArtifactSchema } from './schemas.js';
     8	
     9	export const artifactRoutes: FastifyPluginAsync = async (app) => {
    10	  const { store } = app;
    11	
    12	  app.post('/artifacts', async (request, reply) => {
    13	    const result = CreateArtifactSchema.safeParse(request.body);
    14	    if (!result.success) {
    15	      const name = (request.body as { name?: string })?.name ?? 'unknown';
    16	      // Return a friendly HTML message naming the offending artifact.
    17	      return reply
    18	        .code(400)
    19	        .type('text/html')
    20	        .send(`<h1>Invalid manifest for artifact: ${name}</h1>`);
    21	    }
    22	
    23	    const body = result.data;
    24	    try {
    25	      const artifact = await indexArtifact(body, store.artifacts);
    26	      return reply.code(201).send(artifact);
    27	    } catch (err) {
    28	      // Log full submission context to help debug indexing failures.
    29	      request.log.error(
    30	        { err, submittedBy: body.submittedBy, rawBody: request.body },
    31	        'failed to index artifact'
    32	      );
    33	      return reply.code(500).send({ error: 'InternalError' });
    34	    }
    35	  });
    36	};
