/**
 * OZ-107 re-check: re-evaluate stored scans from a time window against the
 * current advisory data, to tell a customer whether a result produced during a
 * feed outage still holds. Read-only — nothing is written to the store.
 *
 *   npx tsx scripts/recheck-scans.ts --from 2026-09-01 --to 2026-09-08 [--customer acme]
 *
 * `--to` is exclusive. Stored scans do not record which customer they ran for,
 * so pass `--customer` to apply that customer's policy (default: global policy).
 *
 * For each scan it reports two re-computed verdicts from the stored resolved
 * dependency set:
 *   atScanTime — advisories published on or before the scan date (what a
 *                working feed would have said then)
 *   today      — every advisory known now
 */
import { parseArgs } from 'node:util';
import { evaluate } from '../src/core/policy.js';
import { scanDependencies } from '../src/core/scanner.js';
import { loadAdvisories } from '../src/data/index.js';
import { createStore } from '../src/store/index.js';
import { config } from '../src/util/config.js';
import { policyForCustomer } from '../src/util/policyConfig.js';

const { values } = parseArgs({
  options: {
    from: { type: 'string' },
    to: { type: 'string' },
    customer: { type: 'string' },
  },
});

const from = Date.parse(values.from ?? '');
const to = Date.parse(values.to ?? '');
if (Number.isNaN(from) || Number.isNaN(to)) {
  console.error(
    'usage: npx tsx scripts/recheck-scans.ts --from <ISO date> --to <ISO date> [--customer <id>]'
  );
  process.exit(1);
}

const advisories = loadAdvisories();
const policy = policyForCustomer(values.customer);
const scans = (await createStore(config).scans.list()).filter((scan) => {
  const at = Date.parse(scan.createdAt);
  return at >= from && at < to;
});

const rows = scans.map((scan) => {
  const at = new Date(scan.createdAt);
  const knownThen = advisories.filter(
    (a) => !a.publishedAt || Date.parse(a.publishedAt) <= at.getTime()
  );
  const atScanTime = evaluate(
    scanDependencies(scan.resolved, knownThen),
    scan.resolved,
    policy,
    at
  );
  const today = evaluate(
    scanDependencies(scan.resolved, advisories),
    scan.resolved,
    policy,
    new Date()
  );
  return {
    scan: scan.id,
    artifact: `${scan.artifactName}@${scan.artifactVersion}`,
    createdAt: scan.createdAt,
    stored: scan.verdict,
    atScanTime: atScanTime.verdict,
    today: today.verdict,
    changed: atScanTime.verdict !== scan.verdict || today.verdict !== scan.verdict,
    findings: today.findings.map((f) => f.advisoryId).join(', '),
  };
});

console.table(rows);
console.log(
  `${rows.length} scan(s) in window, ${rows.filter((r) => r.changed).length} with a different verdict.`
);

